export type ParsedPostCardInstruction<
  TProgram extends string = typeof PENNY_POST_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>
  accounts: {
    sender: TAccountMetas[0]
    /** is not the sender. */
    recipient: TAccountMetas[1]
    card: TAccountMetas[2]
    vault: TAccountMetas[3]
    /**
     * another letterbox or leave this one out to dodge the reader's price. The
     * reader may not have opened a letterbox yet, so the handler loads it by
     * hand and treats a missing one as "no letterbox".
     */
    recipientLetterbox: TAccountMetas[4]
    senderToken?: TAccountMetas[5] | undefined
    senderSeal?: TAccountMetas[6] | undefined
    postOffice: TAccountMetas[7]
    postageMint: TAccountMetas[8]
    tokenProgram: TAccountMetas[9]
    systemProgram: TAccountMetas[10]
  }
  data: PostCardInstructionData
}

export function parsePostCardInstruction<TProgram extends string, TAccountMetas extends readonly AccountMeta[]>(
  instruction: Instruction<TProgram> & InstructionWithAccounts<TAccountMetas> & InstructionWithData<ReadonlyUint8Array>,
): ParsedPostCardInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 11,
    })
  }
  let accountIndex = 0
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!
    accountIndex += 1
    return accountMeta
  }
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount()
    return accountMeta.address === PENNY_POST_PROGRAM_ADDRESS ? undefined : accountMeta
  }
  return {
    programAddress: instruction.programAddress,
    accounts: {
      sender: getNextAccount(),
      recipient: getNextAccount(),
      card: getNextAccount(),
      vault: getNextAccount(),
      recipientLetterbox: getNextAccount(),
      senderToken: getNextOptionalAccount(),
      senderSeal: getNextOptionalAccount(),
      postOffice: getNextAccount(),
      postageMint: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getPostCardInstructionDataDecoder().decode(instruction.data),
  }
}
